RBinJavaAttrInfo *r_bin_java_attr_info_line_number_table_new(ut8 *buffer, ut64 sz, ut64 buf_offset) {
    RBinJavaAttrInfo *attr = NULL;
    ut2 line_number_table_length = 0;
    RBinJavaAttrLineNumber *line_number = NULL;
    ut64 i = 0;

    if (!buffer || sz < buf_offset + 2) {
        return NULL;
    }

    attr = R_NEW0(RBinJavaAttrInfo);
    if (!attr) {
        return NULL;
    }

    line_number_table_length = READ16(buffer + buf_offset);
    buf_offset += 2;

    attr->line_number_table = R_NEWS0(RBinJavaAttrLineNumber, line_number_table_length);
    if (!attr->line_number_table) {
        free(attr);
        return NULL;
    }

    for (i = 0; i < line_number_table_length; i++) {
        line_number = &attr->line_number_table[i];

