RBinJavaAttrInfo *new_RBinJavaAttrInfo_line_number_table(ut8 *buffer, ut64 sz, ut64 buf_offset) {
    RBinJavaAttrInfo *attr = R_NEW0(RBinJavaAttrInfo);
    if (!attr) {
        return NULL;
    }

    attr->type = R_BIN_JAVA_ATTR_INFO_LINE_NUMBER_TABLE;
    attr->data = NULL;

    // Read line number table length (unsigned short)
    if (buf_offset + 2 > sz) {
        free(attr);
        return NULL;
    }
    attr->length = r_read_le16(buffer + buf_offset);
    ut64 line_number_table_length = attr->length;
    buf_offset += 2;

    // Allocate list for line number table entries
    RBinJavaAttrLineNumber *line_number_table = R_NEWS(RBinJavaAttrLineNumber, line_number_table_length);
    if (!line_number_table) {
        free(attr);
        return NULL;
    }

    for (ut64 i = 0; i < line_number_table_length; i++) {
        if (buf_offset + 4 > sz) {
            r_list_free(attr->data);
            free(attr);
            return NULL;
        }
        line_number_table[i].start_pc = r_read_le16(buffer + buf_offset);
        buf_offset += 2;
        line_number_table[i].line_number = r_read_le16(buffer + buf_offset);
        buf_offset += 2;
    }

    attr->data = line_number_table;
    attr->size = (ut64)(buf_offset - (ut64)(buffer + buf_offset - buffer));
    return attr;
}

RBinJavaAttrInfo *r_bin_java_attr_info_line_number_table_new(ut8 *buffer, ut64 sz, ut64 buf_offset) {
	RBinJavaAttrInfo *attr = NULL;
	ut16 line_number_table_length;
	ut64 i;

	if (!buffer || sz < buf_offset + 2) {
		return NULL;
	}

	attr = R_NEW0(RBinJavaAttrInfo);
	if (!attr) {
		return NULL;
	}

	memcpy (&line_number_table_length, buffer + buf_offset, sizeof (ut16));
	line_number_table_length = R_BIN_ENDIAN (line_number_table_length);

	attr->line_number_table = R_NEWS (ut16 *, line_number_table_length);
	if (!attr->line_number_table) {
		free (attr);
		return NULL;
	}

	for (i = 0; i < line_number_table_length; i++) {
		ut16 start_pc, line_number;
		if (sz < buf_offset + 2 + (i * 4)) {
			r_list_free (attr->line_number_table);
			free (attr);
			return NULL;
		}
		memcpy (&start_pc, buffer + buf_offset + 2 + (i * 4), sizeof (ut16));
		memcpy (&line_number, buffer + buf_offset + 2 + (i * 4) + sizeof (ut16), sizeof (ut16));
		start_pc = R_BIN_ENDIAN (start_pc);
		line_number = R_BIN_ENDIAN (line_number);
		r_list_push (attr->line_number_table, &start_pc, &line_number);
	}

	attr->size = 2 + (line_number_table_length * 4);
	return attr;
}
